/**
 * AI-backed Deal campaign stage generators (AI-FIRST mandate — see TO_FIX.md).
 *
 * Every intelligent stage — angle research, targeting demographic, pitch brief,
 * copy, ad structure, media plan — is generated by a top-tier model through the
 * LLM gateway. There is NO deterministic fallback: if the gateway call fails or
 * times out, the error propagates and the stage produces no output (hard fail).
 * The operator retries. This is intentional — a deterministic scaffold is not an
 * acceptable substitute for reasoning (AI_POLICY §5, TO_FIX foundational rules).
 *
 * Provenance: every generator returns its contract type plus an `aiTrace`
 * (model + prompt sent + raw response + latency) so the operator can inspect
 * exactly what was asked and what came back (Visual Verification principle).
 *
 * Gateway use: all calls go through `generateStructuredObject` with a `ModelName`
 * enum value. No provider SDK is imported here. Zod schemas are kept within the
 * node set the gateway's schema converter supports (object/string/number/boolean/
 * enum/array/record/union/literal/optional).
 */

import { z } from "zod";

import { generateStructuredObject, ModelName } from "@/lib/ai/llm-gateway";

import {
  ANALYST_VOICE_FORBIDDEN,
  buildOfferLines,
  compact,
  detectRedFlags,
  factsDestination,
  QUALIFIER_SUFFIX,
  unique,
  type CampaignStageInputs,
} from "./campaign-generators";
import type {
  DealAdChannelPlan,
  DealAdStructure,
  DealAiGenerationTrace,
  DealCopyPackage,
  DealCtaCopy,
  DealMediaPlan,
  DealPitchBrief,
} from "./campaign-types";
import type { CbPromoIntelligenceRecord } from "./promo-intelligence-types";
import type {
  DealAngleResearch,
  DealResearchCruiseCandidate,
  DealTargetingDemographic,
  RetailDiscoveryBrief,
} from "./research-types";

/** Model used for all Deal reasoning stages (top-tier per AI-FIRST mandate). */
const DEAL_GENERATION_MODEL = ModelName.CLAUDE_4_OPUS;

const DEAL_GENERATION_TIMEOUT_MS = Number(
  process.env.DEAL_GENERATION_TIMEOUT_MS ?? "90000"
);

// ---------------------------------------------------------------------------
// Shared prompt scaffolding
// ---------------------------------------------------------------------------

const GUARDRAILS = `Hard guardrails (never violate):
- Do not invent pricing, onboard credit, cabin availability, or promo eligibility.
- Do not imply a group, hosted event, instructor, workshop, or onboard programming.
- Qualify any perk or savings claim — append: "${QUALIFIER_SUFFIX}"
- Never use: "guaranteed", "lowest price", "free cruise", "always", "no restrictions", "best price ever".
- Base every factual claim only on the cruise facts and promo claims provided.`;

const CUSTOMER_VOICE_RULES = `Customer-voice rules (for any visitor-facing field):
- Write as if speaking to the traveler, not about them.
- Never use analyst/marketing jargon: ${ANALYST_VOICE_FORBIDDEN.join(", ")}.
- Describe the audience as a person ("for travelers who…"), never as a "segment" or "demographic".`;

function factsBlock(input: CampaignStageInputs): string {
  const f = input.cruiseFacts;
  return [
    `Cruise line: ${f.cruiseLine}`,
    `Ship: ${f.shipName}`,
    `Itinerary: ${f.itineraryName}`,
    `Nights: ${f.nights}`,
    `Sail date: ${f.sailDateIso}`,
    f.departurePort ? `Departure port: ${f.departurePort}` : null,
    f.portsOfCall.length ? `Ports of call: ${f.portsOfCall.join(", ")}` : null,
  ]
    .filter(Boolean)
    .join("\n");
}

function promoClaimsBlock(promoRecords?: CbPromoIntelligenceRecord[]): string {
  const claims = (promoRecords ?? []).flatMap((p) => [
    ...p.marketingUse.publicClaimsAllowed,
    ...p.marketingUse.publicClaimsNeedsQualifier,
  ]);
  return claims.length
    ? `Available promo claims (use only these for any savings/perk language):\n- ${claims.join("\n- ")}`
    : "No promo claims provided — do not reference savings, credit, or perks.";
}

function nowIso(input: { generatedAtIso?: string }): string {
  return input.generatedAtIso ?? new Date().toISOString();
}

/**
 * Indirection over the gateway so proof-script tests (run via `tsx`, no mocking
 * framework) can inject a deterministic structured-object generator. Production
 * code never sets this — it defaults to the real gateway call.
 */
type StructuredObjectFn = typeof generateStructuredObject;
let structuredObjectFn: StructuredObjectFn = generateStructuredObject;

/** TEST SEAM: override the gateway generator. Pass no argument to reset. */
export function __setStructuredObjectGeneratorForTests(fn?: StructuredObjectFn): void {
  structuredObjectFn = fn ?? generateStructuredObject;
}

async function generateTraced<TSchema extends z.ZodTypeAny>(args: {
  schema: TSchema;
  system: string;
  prompt: string;
  generatedAtIso: string;
}): Promise<{ object: z.infer<TSchema>; trace: DealAiGenerationTrace }> {
  const startedAt = Date.now();
  const result = await structuredObjectFn({
    model: DEAL_GENERATION_MODEL,
    schema: args.schema,
    system: args.system,
    prompt: args.prompt,
    timeoutMs: DEAL_GENERATION_TIMEOUT_MS,
  });
  const latencyMs = Date.now() - startedAt;
  return {
    object: result.object,
    trace: {
      model: result.modelId,
      promptSent: `SYSTEM:\n${args.system}\n\nPROMPT:\n${args.prompt}`,
      rawResponse: JSON.stringify(result.object, null, 2),
      latencyMs,
      generatedAtIso: args.generatedAtIso,
    },
  };
}

