export async function generateDealTargetingDemographicAi(input: {
  dealId: string;
  packageId: string;
  candidate: DealResearchCruiseCandidate;
  angleResearch: DealAngleResearch;
  retailBrief?: RetailDiscoveryBrief;
  generatedAtIso?: string;
}): Promise<DealTargetingDemographic> {
  const generatedAtIso = nowIso(input);
  const { candidate, angleResearch, retailBrief } = input;

  const system = `You are a cruise retail audience strategist producing an INTERNAL
Targeting-Demographic resource for one sailing. Analyst voice. Define a specific
audience (more precise than "cruise shoppers"), channel-specific targeting for
Meta/Google/TikTok/email, niche keywords, and honest confidence with risks.
${GUARDRAILS}`;

  const prompt = `Recommended angle (from research): ${angleResearch.recommendedPrimaryAngle.title}
Angle rationale: ${angleResearch.recommendedPrimaryAngle.rationale}
Public copy hook: ${angleResearch.recommendedPrimaryAngle.publicCopyHook}
Niche audience angles: ${angleResearch.nicheAudienceAngles.join(", ")}
Trend matches: ${angleResearch.trendMatches.join(", ")}
Competitor blind spots: ${angleResearch.competitorBlindSpots.join(", ")}

Sailing facts:
Cruise line: ${candidate.cruiseLine ?? "unknown"}
Ship: ${candidate.shipName ?? "unknown"}
Itinerary: ${candidate.itineraryName}
Destination: ${candidate.destination}
Nights: ${candidate.nights ?? "unknown"}
Ports of call: ${candidate.portsOfCall.join(", ") || "unknown"}
${
  retailBrief
    ? `\nRetail discovery brief audience: ${retailBrief.audience.label}
Community signals: ${retailBrief.audience.communitySignals.join(", ")}
Targeting seeds (niche): ${retailBrief.targetingSeeds.nicheKeywords.join(", ")}
Targeting seeds (negative): ${retailBrief.targetingSeeds.negativeKeywords.join(", ")}`
    : ""
}

Always include in exclusionKeywords/negativeKeywords at least: "free cruise", "cruise job".
Always include an audience warning against broad cruise-interest targeting as the primary audience.`;

  const { object, trace } = await generateTraced({
    schema: targetingSchema,
    system,
    prompt,
    generatedAtIso,
  });

  return {
    dealId: input.dealId,
    packageId: input.packageId,
    generatedAtIso,
    primaryAudience: object.primaryAudience,
    secondaryAudiences: object.secondaryAudiences,
    nicheKeywords: object.nicheKeywords,
    channelTargeting: object.channelTargeting,
    researchSummary: object.researchSummary,
    sources: [
      ...angleResearch.sources,
      {
        title: retailBrief
          ? `Retail discovery brief: ${retailBrief.retailAngleTitle}`
          : "Cruise candidate facts",
        url: "internal://deals-system/targeting",
        usedFor: "AI Targeting-Demographic generation.",
      },
    ],
    confidence: object.confidence,
    generator: "gpt",
    aiTrace: trace,
  };
}

// ---------------------------------------------------------------------------
// Pitch brief (customer voice — the research→copy boundary, Phase 9B)
// ---------------------------------------------------------------------------

const pitchBriefSchema = z.object({
  tripSummary: z.string(),
  audienceStatement: z.string(),
  primaryHook: z.string(),
  curatedReason: z.string(),
  sellingFacts: z.array(z.string()).min(3).max(3),
  researchRationale: z.string(),
});

export async function generateDealPitchBriefAi(
  input: CampaignStageInputs
): Promise<DealPitchBrief> {
  const generatedAtIso = nowIso(input);
  const { angleResearch, targetingDemographic, campaignStrategy } = input;

  const system = `You write the customer-voice pitch brief that sits between internal
research and public copy. Your job is to find the ONE emotional hook that makes this
sailing feel chosen for a specific traveler, then express four customer-voice decisions.
Every field except researchRationale must read as something a customer would encounter.
researchRationale is INTERNAL ONLY and must never read like customer copy.
${CUSTOMER_VOICE_RULES}
${GUARDRAILS}`;

  const prompt = `${factsBlock(input)}

${
  campaignStrategy
    ? `Operator-selected campaign hook to preserve:
Hook: ${campaignStrategy.campaignAngle}
Audience: ${campaignStrategy.targetAudience}
Visual angle: ${campaignStrategy.visualAngle}
Targeting keywords: ${campaignStrategy.targetingKeywords.join(", ")}
Do not invent a different central promise.`
    : "No operator-selected campaign hook was saved yet."
}

${
  angleResearch
    ? `Research angle: ${angleResearch.recommendedPrimaryAngle.title}
Public copy hook: ${angleResearch.recommendedPrimaryAngle.publicCopyHook}
Why it feels exclusive: ${angleResearch.recommendedPrimaryAngle.whyThisFeelsExclusive}`
    : "No angle research provided."
}
${
  targetingDemographic
    ? `Primary audience: ${targetingDemographic.primaryAudience.label} — ${targetingDemographic.primaryAudience.description}
Emotional drivers: ${targetingDemographic.primaryAudience.emotionalDrivers.join(", ")}`
    : "No targeting provided."
}
${promoClaimsBlock(input.promoRecords)}

Write:
1. tripSummary — one customer-voice sentence naming nights, ship, and a port.
2. audienceStatement — who this is for, stated as a person ("For travelers who…").
3. primaryHook — the single best reason to care (not a perk list).
4. curatedReason — why this feels selected for them, not broadcast to everyone.
5. sellingFacts — EXACTLY 3 short, qualified, public-safe selling facts; each stands alone.
6. researchRationale — INTERNAL note: which research insights drove these decisions.`;

  const { object, trace } = await generateTraced({
    schema: pitchBriefSchema,
    system,
    prompt,
    generatedAtIso,
  });

  const sellingFacts: [string, string, string] = [
    object.sellingFacts[0],
    object.sellingFacts[1],
    object.sellingFacts[2],
  ];

  return {
    dealId: input.dealId,
    packageId: input.packageId,
    generatedAtIso,
    generator: "gpt",
    tripSummary: object.tripSummary,
    audienceStatement: object.audienceStatement,
    primaryHook: campaignStrategy?.campaignAngle.trim() || object.primaryHook,
    curatedReason: campaignStrategy
      ? `${object.curatedReason} Operator-selected campaign hook: ${campaignStrategy.campaignAngle}.`
      : object.curatedReason,
    sellingFacts,
    researchRationale: campaignStrategy
      ? `${object.researchRationale} Operator-selected campaign hook: ${campaignStrategy.campaignAngle}.`
      : object.researchRationale,
    aiTrace: trace,
  };
}

/**
 * Scan a pitch brief's customer-facing fields for leaked analyst/marketing voice.
 * Surfaced in the workbench for the operator; never auto-fixes. researchRationale
 * is internal and intentionally excluded.
 */
export function validatePitchBriefVoice(brief: DealPitchBrief): string[] {
  const customerFields: Array<[string, string]> = [
    ["tripSummary", brief.tripSummary],
    ["audienceStatement", brief.audienceStatement],
    ["primaryHook", brief.primaryHook],
    ["curatedReason", brief.curatedReason],
    ...brief.sellingFacts.map(
      (fact, i) => [`sellingFacts[${i}]`, fact] as [string, string]
    ),
  ];
  const warnings: string[] = [];
  for (const [field, text] of customerFields) {
    const lower = text.toLowerCase();
    for (const phrase of ANALYST_VOICE_FORBIDDEN) {
      if (lower.includes(phrase)) {
        warnings.push(`${field} uses analyst-voice phrase "${phrase}".`);
      }
    }
  }
  return unique(warnings);
}

// ---------------------------------------------------------------------------
// Copy package (customer voice — sourced from the pitch brief)
// ---------------------------------------------------------------------------

const copySchema = z.object({
  headlineOptions: z.array(z.string()).min(1),
  shortTileCopy: z.string(),
  heroCopy: z.string(),
  whyThisTrip: z.array(z.string()).min(1),
});

export async function generateDealCopyPackageAi(
  input: CampaignStageInputs,
  pitchBrief: DealPitchBrief
): Promise<DealCopyPackage> {
  const generatedAtIso = nowIso(input);
  const { offerLines, agentOnlyNotes } = buildOfferLines(input);

  const system = `You write visitor-safe public copy for a cruise Deal page, built
strictly from the supplied pitch brief. Do not introduce facts or offers not present
in the pitch brief or the listed promo claims.
${CUSTOMER_VOICE_RULES}
${GUARDRAILS}`;

  const prompt = `Pitch brief (your only source of positioning):
Trip summary: ${pitchBrief.tripSummary}
Audience: ${pitchBrief.audienceStatement}
Primary hook: ${pitchBrief.primaryHook}
Curated reason: ${pitchBrief.curatedReason}
Selling facts: ${pitchBrief.sellingFacts.join(" | ")}

${factsBlock(input)}
${promoClaimsBlock(input.promoRecords)}

Write:
1. headlineOptions — 3 distinct headline variants; the FIRST must be the primaryHook.
2. shortTileCopy — one short homepage-tile line.
3. heroCopy — hero paragraph; must contain the trip summary verbatim.
4. whyThisTrip — bullet reasons; MUST include all three selling facts verbatim, plus the curated reason.`;

  const { object, trace } = await generateTraced({
    schema: copySchema,
    system,
    prompt,
    generatedAtIso,
  });

  // Enforce the pitch-brief dependency deterministically so copy can never drift
  // from the locked editorial decisions, regardless of model phrasing.
  const headlineOptions = unique([
    pitchBrief.primaryHook,
    ...object.headlineOptions,
  ]);
  const whyThisTrip = unique([
    ...pitchBrief.sellingFacts,
    pitchBrief.curatedReason,
    ...object.whyThisTrip,
  ]);
  const heroCopy = object.heroCopy.includes(pitchBrief.tripSummary)
    ? object.heroCopy
    : `${pitchBrief.tripSummary} ${object.heroCopy}`.trim();

  const ctaCopy: DealCtaCopy[] = [
    {
      kind: "book_now",
      label: "Book now",
      supportingText: "Go straight to the prepared booking link for this sailing.",
    },
    {
      kind: "email_link",
      label: "Email me the booking link",
      supportingText: "We will send the prepared link so you can book when you are ready.",
    },
    {
      kind: "request_callback",
      label: "Request an agent callback",
      supportingText: "A Leisure Life agent will confirm pricing, cabins, and perks with you.",
    },
  ];

  const publicCopyRedFlags = detectRedFlags([
    ...headlineOptions,
    heroCopy,
    object.shortTileCopy,
    ...whyThisTrip,
    ...offerLines.map((line) => line.text),
  ]);

  return {
    dealId: input.dealId,
    packageId: input.packageId,
    generatedAtIso,
    generator: "gpt",
    headlineOptions,
    shortTileCopy: object.shortTileCopy,
    heroCopy,
    whyThisTrip,
    offerLines,
    ctaCopy,
    publicCopyRedFlags,
    agentOnlyNotes,
    aiTrace: trace,
  };
}

