const adChannelSchema = z.object({
  channel: z.enum(["meta", "google", "tiktok", "email"]),
  primaryAngle: z.string(),
  hooks: z.array(z.string()),
  proofPoints: z.array(z.string()),
  notes: z.array(z.string()),
});

const adStructureSchema = z.object({
  campaignThesis: z.string(),
  channels: z.array(adChannelSchema).min(1),
  nicheKeywords: z.array(z.string()),
  trendKeywords: z.array(z.string()),
  negativeKeywords: z.array(z.string()),
  creativeHypotheses: z.array(z.string()),
});

export async function generateDealAdStructureAi(
  input: CampaignStageInputs
): Promise<DealAdStructure> {
  const generatedAtIso = nowIso(input);
  const { targetingDemographic, angleResearch } = input;

  const offerProofPoints = unique(
    compact([
      ...(input.promoRecords ?? []).flatMap((promo) =>
        promo.marketingUse.publicClaimsAllowed.slice(0, 2)
      ),
      input.cruiseFacts.portsOfCall.length > 0
        ? `Itinerary highlights: ${input.cruiseFacts.portsOfCall.slice(0, 4).join(", ")}.`
        : "",
      `${input.cruiseFacts.nights} nights on ${input.cruiseFacts.shipName}.`,
    ])
  );

  const system = `You design an INTERNAL paid-media campaign structure for one cruise Deal:
a thesis, channel plans for Meta/Google/TikTok/email, keyword sets, and creative hypotheses.
Lead with the niche angle, not a generic price-led cruise pitch.
${GUARDRAILS}`;

  const prompt = `${factsBlock(input)}

${
  angleResearch
    ? `Campaign angle: ${angleResearch.recommendedPrimaryAngle.title}
Rationale: ${angleResearch.recommendedPrimaryAngle.rationale}
Competitor blind spots: ${angleResearch.competitorBlindSpots.join(", ")}`
    : ""
}
${
  targetingDemographic
    ? `Primary audience: ${targetingDemographic.primaryAudience.label}
Meta creative hooks: ${targetingDemographic.channelTargeting.meta.creativeHooks.join(", ")}
Google search themes: ${targetingDemographic.channelTargeting.google.searchThemes.join(", ")}
TikTok creator angles: ${targetingDemographic.channelTargeting.tiktok.creatorAngles.join(", ")}
Email subject angles: ${targetingDemographic.channelTargeting.email.subjectLineAngles.join(", ")}
Niche keywords (lifestyle): ${targetingDemographic.nicheKeywords.lifestyle.join(", ")}`
    : "No targeting provided — derive channel plans from the facts and angle."
}
Verified offer proof points (use these): ${offerProofPoints.join(" | ")}

Produce a plan covering all four channels (meta, google, tiktok, email). Always include
"free cruise" and "cruise job" among negativeKeywords.`;

  const { object, trace } = await generateTraced({
    schema: adStructureSchema,
    system,
    prompt,
    generatedAtIso,
  });

  const channels: DealAdChannelPlan[] = object.channels.map((c) => ({
    channel: c.channel,
    primaryAngle: c.primaryAngle,
    hooks: unique(c.hooks),
    proofPoints: unique([...c.proofPoints, ...offerProofPoints]).slice(0, 4),
    notes: c.notes,
  }));

  return {
    dealId: input.dealId,
    packageId: input.packageId,
    generatedAtIso,
    generator: "gpt",
    campaignThesis: object.campaignThesis,
    channels,
    nicheKeywords: unique(object.nicheKeywords).slice(0, 24),
    trendKeywords: unique(object.trendKeywords).slice(0, 16),
    negativeKeywords: unique([...object.negativeKeywords, "free cruise", "cruise job"]),
    creativeHypotheses: unique(object.creativeHypotheses),
    offerProofPoints,
    aiTrace: trace,
  };
}

