const mediaSchema = z.object({
  visualDirection: z.array(z.string()).min(1),
  imageSlots: z
    .array(
      z.object({
        slot: z.string(),
        purpose: z.string(),
        visualConceptPrompt: z.string(),
        requiredSourceAssets: z.array(z.string()),
      })
    )
    .min(1),
  shortVideoConcepts: z.array(
    z.object({
      concept: z.string(),
      hook: z.string(),
      shots: z.array(z.string()),
    })
  ),
  requiredSourceAssets: z.array(z.string()),
});

export async function generateDealMediaPlanAi(
  input: CampaignStageInputs
): Promise<DealMediaPlan> {
  const generatedAtIso = nowIso(input);
  const dest = factsDestination(input.cruiseFacts);

  const system = `You produce an INTERNAL media plan for one cruise Deal: image-slot
visual concept prompts, short-video concepts, and the source assets needed. Concepts
must support the niche angle, be photo-real, and carry no on-image text.
${GUARDRAILS}`;

  const prompt = `${factsBlock(input)}

${
  input.angleResearch
    ? `Angle: ${input.angleResearch.recommendedPrimaryAngle.title}
Public copy hook: ${input.angleResearch.recommendedPrimaryAngle.publicCopyHook}
Destination hooks: ${input.angleResearch.destinationHooks.join(", ")}`
    : ""
}
${
  input.targetingDemographic
    ? `TikTok short-video concepts to draw from: ${input.targetingDemographic.channelTargeting.tiktok.shortVideoConcepts.join(", ")}`
    : ""
}

Produce at least a "hero", a "ship_experience", and a "destination_detail" image slot,
each with a visual concept prompt and the source assets it needs. Include 1-2 short
video concepts with shot lists, and the overall required source asset list.
Anchor destination scenes on: ${dest}.`;

  const { object, trace } = await generateTraced({
    schema: mediaSchema,
    system,
    prompt,
    generatedAtIso,
  });

  return {
    dealId: input.dealId,
    packageId: input.packageId,
    generatedAtIso,
    generator: "gpt",
    visualDirection: unique(object.visualDirection),
    imageSlots: object.imageSlots,
    shortVideoConcepts: object.shortVideoConcepts,
    requiredSourceAssets: unique(object.requiredSourceAssets),
    readiness: "concepts_ready",
    aiTrace: trace,
  };
}
